[meta]
name = The Cinderhold
ambient = 0.46 0.34 0.30
fog = 0.22 0.08 0.05
fog_range = 20 100
sky = ember
atlas = cinderhold
model_range = 46
indoor_range = 26
torch = 7 0.9 0.7 0.5
start = 30 111 -90
default = ,
edge_top = 16
edge_tex = black_brick
entity_floor = auto
roofs = true
crack_span = 20
crack_run = 2
crack_seep = 0.5

[legend]
// The great wall, cracked down its tall faces by the heat of the fires behind it, which glow through
// many of its cracks (`crack_seep`); its great windows leave bays only two tiles wide (`crack_run`).
K = wall tex=black_brick top=16 cap=slate dress=cracks
] = wall tex=black_brick top=11 cap=slate
~ = floor tex=slate h=8 side=black_brick
# = wall tex=black_brick top=8 cap=slate
p = wall tex=black_brick top=7.2 cap=black_brick
P = wall tex=black_brick top=13.2 cap=black_brick
A = wall tex=cliff_rock top=7 cap=cliff_rock
// The cliffs walling the lava moat, split by the heat.
Ŧ = wall tex=cliff_rock top=7 cap=cliff_rock dress=cracks
r = wall tex=black_brick top=1.0 cap=black_brick
, = floor tex=ash_road h=0 side=cliff_rock
= = floor tex=flagstone h=0 side=black_brick
_ = floor tex=lava h=-8 side=cliff_rock chasm
^ = floor tex=slate h=16 side=black_brick
$ = floor tex=flagstone h=3 side=black_brick
. = floor tex=iron_plate h=0 ceil=6 ceil_tex=black_brick side=black_brick roof_tex=slate
// The passages through the great wall: the wall runs on unbroken over them.
; = floor tex=iron_plate h=0 ceil=6 ceil_tex=black_brick side=black_brick roof=16 roof_tex=slate
: = floor tex=slag h=0 side=black_brick
g = floor tex=iron_grate h=0 ceil=6 ceil_tex=black_brick side=black_brick roof_tex=slate
l = floor tex=lava h=-1 ceil=6 ceil_tex=black_brick side=black_brick lava roof_tex=slate
R = floor tex=flagstone h=6 side=black_brick
+ = floor tex=flagstone h=6 ceil=10.4 ceil_tex=black_brick side=black_brick roof_tex=slate
o = floor tex=slate h=12 side=black_brick
s = floor tex=slag h=-3.8 ceil=0.2 ceil_tex=black_brick side=black_brick dark=0.6 roof_tex=slate
v = floor tex=lava h=-4.8 ceil=0.2 ceil_tex=black_brick side=black_brick lava roof_tex=slate
| = floor tex=iron_grate h=-3.8 ceil=6 ceil_tex=black_brick side=black_brick chasm roof_tex=slate
a = floor tex=flagstone h=0.5 side=black_brick
b = floor tex=flagstone h=1 side=black_brick
c = floor tex=flagstone h=1.5 side=black_brick
d = floor tex=flagstone h=2 side=black_brick
e = floor tex=flagstone h=2.5 side=black_brick
f = floor tex=flagstone h=3 side=black_brick
h = floor tex=flagstone h=3.5 side=black_brick
i = floor tex=flagstone h=4 side=black_brick
j = floor tex=flagstone h=4.5 side=black_brick
k = floor tex=flagstone h=5 side=black_brick
m = floor tex=flagstone h=5.5 side=black_brick
n = floor tex=flagstone h=6 side=black_brick
q = floor tex=flagstone h=6.5 side=black_brick
t = floor tex=flagstone h=7 side=black_brick
u = floor tex=flagstone h=7.5 side=black_brick
w = floor tex=flagstone h=8 side=black_brick
x = floor tex=flagstone h=8.5 side=black_brick
y = floor tex=flagstone h=9 side=black_brick
z = floor tex=flagstone h=9.5 side=black_brick
0 = floor tex=flagstone h=10 side=black_brick
8 = floor tex=flagstone h=10.5 side=black_brick
9 = floor tex=flagstone h=11 side=black_brick
! = floor tex=flagstone h=11.5 side=black_brick
1 = floor tex=slag h=-0.55 ceil=3 ceil_tex=black_brick side=black_brick dark=0.1 roof_tex=slate
2 = floor tex=slag h=-1.1 ceil=3 ceil_tex=black_brick side=black_brick dark=0.2 roof_tex=slate
3 = floor tex=slag h=-1.65 ceil=3 ceil_tex=black_brick side=black_brick dark=0.3 roof_tex=slate
4 = floor tex=slag h=-2.2 ceil=3 ceil_tex=black_brick side=black_brick dark=0.4 roof_tex=slate
5 = floor tex=slag h=-2.75 ceil=3 ceil_tex=black_brick side=black_brick dark=0.5 roof_tex=slate
6 = floor tex=slag h=-3.3 ceil=3 ceil_tex=black_brick side=black_brick dark=0.6 roof_tex=slate
// The crags round the fen's flanks and its south, broken and lower toward the mire, so the burnt hills
// and the storm on the Hollow Peak show over them.
Ą = wall tex=cliff_rock top=3.6 cap=cliff_rock
ą = wall tex=cliff_rock top=4.6 cap=cliff_rock
Ć = wall tex=cliff_rock top=5.6 cap=cliff_rock
// The Sallow Fen below the cliffs, fouled violet by the fortress's runoff: wading its mire works a toxin
// into you (deeper, faster), its banks and islands are sucking mud, and its sink-holes drown.
- = floor tex=sallow_mire h=-0.3 side=fen_mud slow=0.6 afflict=toxic:7
* = floor tex=sallow_mire h=-0.5 side=fen_mud slow=0.45 afflict=toxic:11
7 = floor tex=fen_mud h=0 side=fen_mud slow=0.85
? = floor tex=fen_mud h=0 side=fen_mud slow=0.85 dark=0.25
& = floor tex=flagstone h=0 side=fen_mud
% = water tex=sallow_mire h=-0.6 side=fen_mud drown=mire
// The dry ways through it: dirt paths raised a hand over the mire, and mounds of firm earth (each step
// up half a metre at most) where the great dead trees stand. No toxin works into you on either.
@ = floor tex=dirt_path h=0.1 side=fen_mud
[ = floor tex=dirt_hill h=0.2 side=fen_mud
( = floor tex=dirt_hill h=0.7 side=fen_mud
) = floor tex=dirt_hill h=1.2 side=fen_mud
// The great square: the flagstones of the marsh-folk's old moot, an island ringed by sink-holes. The
// great rotten bridge out to it is decked in rotten timber; its rotting planks span a shallow, fouled
// pool that will not drown you, but sickens you and spits you back onto the last sound timber.
< = floor tex=flagstone h=0.3 side=fen_mud
{ = floor tex=rotten_wood h=0.2 side=fen_mud
> = water tex=sallow_mire h=-0.6 side=fen_mud afflict=toxic:45
// The sunken ways: old stone-lined trenches the marsh-folk cut below the mire out to two of the beacon
// islands, their low walls holding the violet water back, so you walk them dry under its surface.
Ď = floor tex=cobble_moss h=-0.9 side=rough_stone
ď = floor tex=cobble_moss h=-0.4 side=rough_stone
Đ = wall tex=rough_stone top=0.8 cap=rough_stone
// Broken stretches of the marsh-folk's walls, standing out of the mire.
đ = wall tex=rough_stone top=1.4 cap=rough_stone
Ē = wall tex=rough_stone top=2.4 cap=rough_stone
// The fortress's curtain wall closing the fen's north side, and the two towers of its great gate.
ē = wall tex=black_brick top=9 cap=slate dress=rampart,cracks
Ĕ = wall tex=black_brick top=13 cap=slate

