[entities]
// The Sallow Fen: the north road from Harrowmere comes down into it. Three beacons of the fortress's violet
// fire burn on its islands, and the fen gate up to the ash road stays shut until all three are smothered.
// A dirt path winds north from the watch-post shrine to the great rotten bridge, which crosses a lagoon
// of sink-holes out to the great square, the marsh-folk's old moot: two of its spans are rotting planks
// that sink under you if you linger. The rotten lever at the square's heart lets down two great rotten
// drawbridges, north to the path up to the gate and east toward the east beacon, so that, once it is
// pulled, the fen can be crossed dry. Fen Lurks squat in the mire, Bileguts crawl its banks, and the Mire
// Tyrant keeps the north island. Great dead trees stand on the dirt mounds and loom over the mire.
// Two sunken ways, walled trenches below the mire, run dry out to the west and north-east beacons, and
// the fen's north side is the fortress's curtain wall, its great gate between two towers.
// The fen is a region of its own: its name rises as you come down into it, the Cinderhold's as you go
// up through the fen gate onto the Gargoyle Way (`world/regions.py`; a band of markers either side).
Ċ = region name="Sallow Fen" on=7
ċ = region name="The Cinderhold"
ý = hint text="The mire is fouled violet. Wading it works a toxin into your blood.|Three beacons burn on the fen. Smother them, and the gate north opens.|The old moot's planks are rotten. Do not linger on them." sets=visited_sallow_fen
ï = fen_beacon gate=fen_beacons
ð = gate lever=fen_beacons model=great on=,
// Torchlight before the great gate, so its stone shows from the fen.
ė = light y=5 color=0.9,0.6,0.45 radius=9
¤ = lever id=fen_causeway model=rotten on=<
¥ = bridge lever=fen_causeway hinge=s deck=0.3 on=% model=rotten
¦ = bridge lever=fen_causeway hinge=w deck=0.3 on=% model=rotten
§ = plank deck=0.2 on=>
ì = fen_lurk
í = bilegut
ĕ = bilegut on=Ď
î = mire_tyrant item=fenbane
ù = chest item=fenbane count=2 gold=40 model=worn
ú = chest item=blue_moss count=2 gold=90 model=worn
û = chest item=menders_kit count=2 gold=120 model=worn
ò = dead_cypress
ó = fen_reeds
ô = sunken_hut yaw=90
õ = stilt_posts
¬ = stilt_posts on=%
¶ = huge_rotten_tree on=)
· = huge_rotten_tree size=1.25
° = huge_rotten_tree size=0.8
þ = light y=0.6 color=0.75,0.35,1.0 radius=6
// The Gargoyle Way: the ash road runs straight from the fen gate up to the long bridge, staked with
// warnings at the gate, gargoyles crouched in facing pairs in niches in its cliffs, torches between them,
// and the wayside shrine in its own court off the road's east side.
ā = gargoyle_statue yaw=0
Ā = gargoyle_statue yaw=180
ă = gargoyle_statue pose=snarl yaw=0
Ă = gargoyle_statue pose=snarl yaw=180
Ð = exit map=harrowmere at=10,2,90 label=Return_to_Harrowmere model=road_gate yaw=90
ä = light y=4.5 color=0.9,0.62,0.42 radius=7
Ñ = save_statue
T = torch radius=7
// The long bridge: vents in the lava lob bombs onto it; hounds and bowmen hold it.
V = magma_vent radius=18 every=3.6 on=_
Ä = magma_vent radius=18 every=4.2 phase=1.8 on=_
H = slag_hound
B = iron_bowman
J = flame_jet dir=s len=1 every=3.2
Þ = flame_jet dir=s len=1 every=3.2 phase=1.1
ß = flame_jet dir=s len=1 every=3.2 phase=2.2
E = embers
// The skyline over the front wall, no two towers alike: a smelter stack, a drum bastion, a second
// bastion and the great gatehouse closing the gaps above the passages, a tall spire, a lesser stack
// and a stubby beacon tower; the keep rises behind them, and molten iron pours into the moat.
Ë = smokestack height=18 on=^
Ê = bastion top=6 radius=2.2 on=^
É = bastion base=6.2 top=14 radius=2.6 on=;
È = gatehouse on=;
Ò = spire height=14 width=2.2 on=^
Ì = smokestack height=10 on=^
Ø = spire height=7 width=2.8 roof=flat on=^
Í = keep on=~
Î = lavafall top=22 spout=gargoyle on=_
G = gate lever=hold_gate on=;
Ó = door model=iron on=;
// The gatehouse: a shrine, and the winch that raises the main gate.
Ô = save_statue
Õ = lever id=hold_gate
Q = chest item=red_tonic count=2 gold=60 model=iron
Z = brazier radius=9
W = cinder_wisp
Ö = door key=forge_key model=iron on=+
// The foundry and the smelter pits below it.
F = forge_golem
X = chest item=scroll_thunder gold=40 model=iron
M = mimic model=iron
N = anvil
Y = chest item=forge_key gold=50 model=iron
U = chest item=menders_kit count=2 gold=90 model=iron
D = lift top=0 locked on=|
// The ashworks: a gauntlet of flame jets, and a forge with a false wall.
I = chest item=blue_moss count=3 gold=120 model=iron
Ù = secret_wall
Ç = chest item=stormbrand model=iron
// The rampart, and the tower stair up to the keep, where the gargoyles perch on its roof.
O = chest item=slagbreaker model=iron
Ü = chest item=scroll_motes gold=60 model=iron
S = exit map=cinder_keep at=25,22,180 label=Enter_the_keep model=keep_door boss=gargoyles_dead on=o
// Dressing: gargoyles carved for the fortress, barred windows lit by the forges within, and the
// clutter of the smiths; the road up is staked with warnings.
C = gargoyle_statue
L = gargoyle_statue pose=snarl
À = barred_window
Á = forge_hearth
Â = crucible
Ã = quench_trough
Å = tool_rack
Æ = ingot_pile
Ï = slag_heap
Ú = impaler
// A smith-knight cast in iron over the foundry, and ore carts left on their rails.
¡ = forge_statue yaw=0
¢ = ore_cart yaw=90
£ = ore_cart yaw=0
Û = rubble
Ý = bones
à = crate
á = barrel
â = candles
ã = banner burnt
å = chains
// The great wall's crenellated walk, run along its top behind the skyline.
æ = battlement span=10 on=^
ç = battlement span=6 on=^
